UPDATE public.storm_events se SET config_snapshot=se.config_snapshot || jsonb_build_object('field_definitions',tt.field_definitions,'default_values',tt.default_values,'payload_version',tt.payload_version) FROM public.ticket_templates tt WHERE tt.template_key=se.ticket_template_key AND tt.utility_client=se.utility_client AND NOT (se.config_snapshot ? 'field_definitions');
